mapper.select:
select count(*) from rp_var_drug_evw

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}

select record_id,lang, gene,variant,ori_variant,disease_id,disease_name_chinese,var_drug_desc,drugsA,drugsB,drugsC,drugsD,resistant_drugs,clinical_trial,modified,update_by,date_format(update_date,'%Y-%m-%d %H:%i:%s') as update_date,date_format(check_date,'%Y-%m-%d %H:%i:%s') as check_date 
from rp_var_drug_evw

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}


limit #{pageNo},#{pageSize}

select gene,lang,variant,ori_variant,disease_id,disease_name_chinese,var_drug_desc,drugsA,drugsB,drugsC,drugsD,resistant_drugs,clinical_trial,modified,update_by,date_format(update_date,'%Y-%m-%d %H:%i:%s') as update_date ,date_format(check_date,'%Y-%m-%d %H:%i:%s') as check_date
from rp_var_drug_evw

	modified=1

		and update_date >= #{before_date}


		and update_date < #{after_date}
